import {fresh,calculate,classes} from './model.js';
import {makePreset} from './presets.js';
export const reduction=(value,level)=>Math.min(.95,value/(40*level+value-25));
export const hitChance=(accuracy,evasion)=>2*accuracy+evasion===0?null:2*accuracy/(2*accuracy+evasion);
export function referenceEnemies(items){
 const build=(classId,id)=>calculate(makePreset({...fresh(classId),level:55,world:'ostrog'},items,id),items);
 return {archer:build('archer','archer')};
}
export function combatTip(key,s,r,enemies){
 const n=x=>Number(x.toFixed(1)).toLocaleString('ru-RU'),pct=x=>n(x*100)+'%',range=a=>a.map(n).join('–'),magic=classes[s.classId].stat==='magic';
 const ar=enemies.archer,hit=magic?1:hitChance(r.accuracy,ar.evasion),armor=magic?ar.resistance:ar.defense,dr=reduction(armor,s.level),mean=(r.attack[0]+r.attack[1])/2;
 const vsArcher=`Цель 55 ур.: защита ${n(ar.defense)}, сопра ${n(ar.resistance)}, уклонение ${n(ar.evasion)}.`,rows=[];
 const add=(text,formula)=>rows.push([text,formula]);let title='';
 if(key==='defense'||key==='resistance'){
  const physical=key==='defense',enemy=ar,value=r[key],reduced=reduction(value,55);title=physical?'Защита':'Сопротивление';
  add(`Снижение ${physical?'физического':'магического'} урона: ${pct(reduced)}. Проходит ${pct(1-reduced)}.`,`Снижение = min(95%, ${title} / (40 × уровень атакующего + ${title} − 25)).`);
  add(`Противник 55 ур.${physical?'':' (условно магический урон)'}: базовый удар ${range(enemy.attack)} → ${range(enemy.attack.map(x=>x*(1-reduced)))} после ${physical?'защиты':'сопротивления'}.`,`Урон после брони = базовый урон × (1 − снижение).${physical?'':' Условность: меняем только тип урона противника на магический; уровень и диапазон атаки сохраняются.'}`);
  add(`Ещё 100 ед. дадут снижение ${pct(reduction(value+100,55))}.`,`Для сравнения подставляем ${title} + 100 в ту же формулу.`);
  add('Пример без крита, множителя умения и отдельных эффектов снижения урона. Тики DOT тоже учитывают защиту/сопротивление по типу урона. Когда фиксируется броня — при наложении или на каждом тике — пока неизвестно.','Финальный прямой урон = урон × (1 − отдельные эффекты снижения) × (1 − снижение от брони).');
 }
 if(key==='evasion'){
  title='Уклонение';const h=hitChance(ar.accuracy,r.evasion);
  add(`При меткости противника ${n(ar.accuracy)}: ${pct(1-h)} уклонения.`,`Шанс уклонения = Уклонение / (2 × меткость врага + Уклонение).`);
  add(`Вероятность попадания противника: ${pct(h)}.`,`Шанс попадания = 1 − шанс уклонения.`);
  add('Маг и жрец игнорируют обычную проверку меткости/уклонения. Бег — отдельная проверка, здесь не включён.','Итоговый шанс попадания при беге = обычный шанс × (1 − шанс уклонения от бега), если применимо.');
 }
 if(key==='accuracy'){
  title='Меткость';add(vsArcher,'Шанс попадания = 2 × Меткость / (2 × Меткость + уклонение цели).');
  add(magic?'Умения этого класса попадают со 100% шансом в обычной проверке; меткость не увеличивает его.':`Шанс попадания: ${pct(hit)}; промаха: ${pct(1-hit)}.`,magic?'Для мага/жреца обычная проверка меткости пропускается.':'Средний урон с промахами = средний урон попадания × шанс попадания.');
 }
 if(key==='attack'){
  title=r.attackLabel;add(vsArcher,`Базовый урон = (атака вещей + уровень) × (1 + ${magic?'Интеллект / 100':'основной стат / 150'} + пассивки + баффы).`);
  add(`По цели: ${range(r.attack.map(x=>x*(1-dr)))} за попадание без крита. Снижение цели: ${pct(dr)}.`,`Урон попадания = базовый урон × (1 − снижение цели); уровень атакующего = ${s.level}.`);
  add(`Средний урон попытки с критом и промахами: ${n(mean*(1-dr)*(1+r.crit/100)*hit)}.`,`Среднее = (мин. + макс.) / 2 × (1 − снижение) × (1 + шанс крита) × шанс попадания. Крит ×2.`);
  add('Это базовая атака, не DPS и не урон конкретного умения. Среднее предполагает равномерный разброс.','Урон умения требует его множителя, числа попаданий и отдельных эффектов. DPS также требует длительности ротации.');
 }
 if(key==='crit'){
  title='Шанс критического удара';add(`Крит ×2; ${r.crit}% шанса дают +${r.crit}% к среднему прямому урону относительно урона без критов.`,`Средний множитель = 1 + шанс крита × (2 − 1).`);
  add(`По цели средний урон попытки: ${n(mean*(1-dr)*hit)} без критов → ${n(mean*(1-dr)*hit*(1+r.crit/100))} с критами.`,`Шанс крита = min(100%, 1% + floor(Ловкость / 20)% + бонусы вещей).`);
  add('Тики DOT не критуют; удар, накладывающий DOT, может критовать.','К тикам DOT множитель крита не применяется.');
 }
 if(key==='activation'){
  title='Время активации';add(`Каст занимает ${r.activation}% исходного времени: сокращение на ${100-r.activation}%. Каст 2 с → ${n(2*r.activation/100)} с.`,`Время каста = исходное время × max(10%, 100% − сумма ВА).`);
  add(`За время непрерывных кастов без отката: в ${n(100/r.activation)} раза больше завершённых кастов. Это не готовый множитель DPS.`,`Цикл одного умения = время каста × ВА / 100 + откат. Откат начинается после завершения каста.`);
  add(`Для сравнения: время активации ${ar.activation}%.`,`Сравнение времени одинакового каста: ваша ВА / ВА цели.`);
 }
 if(key==='attackSpeed'){
  title='Ударов в секунду';
  if(magic)add('У мага и жреца нет автоатаки.','Скорость применения умений зависит от времени каста и ВА.');
  else {
   const sec=x=>Number((x/1000).toFixed(3)).toLocaleString('ru-RU');
   add(`Базовый интервал оружия: ${sec(r.attackIntervalBase)} с. Без оружия — 1 с.`,`Базовый интервал берётся с оружия; без оружия = 1000 мс.`);
   add(`Сокращение от ПМА: ${sec(r.attackIntervalReduction)} с. Итоговый интервал: ${sec(r.attackInterval)} с.`,`Интервал = ${sec(r.attackIntervalBase)} − ${sec(r.attackIntervalReduction)} = ${sec(r.attackInterval)} с.`);
   add(r.attacksPerSecond===null?'Минимальный интервал при таком сокращении пока неизвестен.':`Частота автоатак: ${Number(r.attacksPerSecond.toFixed(3)).toLocaleString('ru-RU')} уд/с.`,r.attacksPerSecond===null?'При нулевом или отрицательном интервале частота не рассчитывается.':`Ударов в секунду = 1 / ${sec(r.attackInterval)} = ${Number(r.attacksPerSecond.toFixed(3)).toLocaleString('ru-RU')}. ВА не влияет на автоатаку.`);
  }
 }
 if(key==='health'){
  title='Здоровье';if(r.hp===null)add(`Известна только прибавка: +${n(r.hpBonus)} HP до баффа. Задайте исходные HP, чтобы оценить выживаемость.`,`HP = (исходные HP + прибавка от живучести + HP вещей) × (1 + бафф HP).`);
  else{add(`Текущие HP: ${n(r.hp)}. Эквивалент запаса до брони: ${n(r.hp/(1-reduction(r.defense,55)))} физического или ${n(r.hp/(1-reduction(r.resistance,55)))} магического урона.`,`Эффективные HP = HP / (1 − снижение от брони).`);add('Без лечения, уклонений, DOT и отдельных эффектов снижения. Для выживания итоговый удар должен быть меньше текущих HP.','Выживание одного попадания: HP > итоговый урон.');}
 }
 if(key==='mana'){
  title='Мана';add(r.mana===null?`Известна прибавка +${n(r.manaBonus)}. Полный запас требует исходной маны.`:`Запас маны: ${n(r.mana)}. Сам по себе запас не усиливает урон.`,`Мана = исходная при 5 интеллекта + (Интеллект − 5) × ${classes[s.classId].mana} + мана вещей.`);
  add('Число применений зависит от стоимости умения и регенерации. Мана списывается при успешном касте.','Применений без регенерации = floor(Мана / стоимость умения).');
 }
 return {title,rows};
}
